import React, { useState } from "react";
import axios from "axios";

function CourseWithSyllabusForm() {
  const [courseData, setCourseData] = useState({
    course_name: "",
    course_log: null,
    course_duration: "",
    course_fee: "",
    course_description: "",
    course_level: "Beginner",
  });

  const [syllabus, setSyllabus] = useState([
    { module: "", description: "" },
  ]);

  // Course input change
  const handleCourseChange = (e) => {
    const { name, value } = e.target;
    setCourseData({ ...courseData, [name]: value });
  };

  // Image change
  const handleImageChange = (e) => {
    setCourseData({ ...courseData, course_log: e.target.files[0] });
  };

  // Syllabus change
  const handleSyllabusChange = (index, e) => {
    const { name, value } = e.target;
    const updatedSyllabus = [...syllabus];
    updatedSyllabus[index][name] = value;
    setSyllabus(updatedSyllabus);
  };

  // Add new syllabus row
  const addSyllabus = () => {
    setSyllabus([...syllabus, { module: "", description: "" }]);
  };

  // Submit form
 const handleSubmit = async (e) => {
  e.preventDefault();

  try {
    // ===============================
    // 1️⃣ CREATE COURSE
    // ===============================
    const formData = new FormData();
    console
    Object.keys(courseData).forEach((key) => {
      formData.append(key, courseData[key]);
    });

    const courseResponse = await axios.post(
      "http://127.0.0.1:8000/VJISS/add_course",
      formData,
      { headers: { "Content-Type": "multipart/form-data" } }
    );

    console.log("Course Created:", courseResponse.data);

    const courseId = courseResponse.data.public_id;

    // ===============================
    // 2️⃣ CREATE SYLLABUS
    // ===============================
    await axios.post(
      "http://127.0.0.1:8000/VJISS/add_syllabus",
      {
        course_id: courseId,
        syllabus: syllabus,
      }
    );

    alert("Course and Syllabus created successfully");

  } catch (error) {
    console.error("Error:", error);
    alert("Something went wrong");
  }
};


  return (
    <div>
      <h2>Create Course</h2>

      <form onSubmit={handleSubmit} encType="multipart/form-data">
        {/* Course Fields */}
        <input
          type="text"
          name="course_name"
          placeholder="Course Name"
          onChange={handleCourseChange}
          required
        />

        <input
          type="file"
          name="course_log"
          onChange={handleImageChange}
          required
        />

        <input
          type="text"
          name="course_duration"
          placeholder="Duration"
          onChange={handleCourseChange}
        />

        <input
          type="number"
          name="course_fee"
          placeholder="Fee"
          onChange={handleCourseChange}
        />

        <textarea
          name="course_description"
          placeholder="Description"
          onChange={handleCourseChange}
        />

        <select
          name="course_level"
          onChange={handleCourseChange}
        >
          <option value="Beginner">Beginner</option>
          <option value="Intermediate">Intermediate</option>
          <option value="Advanced">Advanced</option>
        </select>

        <hr />

        {/* Syllabus Section */}
        <h3>Syllabus</h3>

        {syllabus.map((item, index) => (
          <div key={index}>
            <input
              type="text"
              name="module"
              placeholder="Module Name"
              value={item.module}
              onChange={(e) => handleSyllabusChange(index, e)}
            />

            <textarea
              name="description"
              placeholder="Module Description"
              value={item.description}
              onChange={(e) => handleSyllabusChange(index, e)}
            />
          </div>
        ))}

        <button type="button" onClick={addSyllabus}>
          + Add Module
        </button>

        <br /><br />

        <button type="submit">Submit Course</button>
      </form>
    </div>
  );
}

export default CourseWithSyllabusForm;
